smart.css:
.smc-root {
  color: var(--smc-text, #1e293b);
  font-family: var(--smc-font-body, system-ui, -apple-system, sans-serif);
  font-size: 16.5px;
  line-height: 1.8;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary, #0f172a);
  font-family: var(--smc-font-heading, inherit);
  font-weight: 700;
  line-height: 1.35;
}

.smc-root h2 {
  font-size: clamp(22px, 3.5vw, 29px);
  margin: 38px 0 16px;
  padding-bottom: 10px;
  border-bottom: 2px solid color-mix(in srgb, var(--smc-primary, #0f172a) 15%, transparent);
}

.smc-root h3 {
  font-size: 18.5px;
  margin: 26px 0 10px;
  color: var(--smc-primary, #0f172a);
}

.smc-root p {
  margin: 0 0 16px;
}

.smc-root a {
  color: var(--smc-accent, #c2410c);
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.smc-root a:hover {
  color: var(--smc-primary, #0f172a);
}

.smc-root table {
  width: 100%;
  margin: 22px 0 32px;
  border-collapse: collapse;
  border-radius: var(--smc-radius, 8px);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}

.smc-root th,
.smc-root td {
  padding: 14px 16px;
  border: 1px solid var(--smc-border, #e2e8f0);
  text-align: left;
}

.smc-root th {
  background: var(--smc-primary, #0f172a);
  color: #ffffff;
  font-weight: 650;
  font-size: 15px;
}

.smc-root tbody tr:nth-child(even) {
  background: var(--smc-surface, #f8fafc);
}

.smc-figure {
  margin: 26px 0 32px;
  text-align: center;
}

.smc-figure img {
  max-width: 100%;
  height: auto;
  border-radius: var(--smc-radius, 8px);
  box-shadow: 0 4px 14px rgba(0,0,0,0.08);
}

.smc-figure figcaption {
  font-size: 14px;
  color: #64748b;
  margin-top: 10px;
  font-style: italic;
}

.smc-cluster-box {
  margin: 36px 0;
  padding: 24px;
  background: color-mix(in srgb, var(--smc-primary, #0f172a) 4%, #ffffff);
  border: 1px solid color-mix(in srgb, var(--smc-primary, #0f172a) 15%, transparent);
  border-left: 4px solid var(--smc-accent, #c2410c);
  border-radius: var(--smc-radius, 8px);
}

.smc-cluster-box h4 {
  margin: 0 0 12px;
  font-size: 17px;
  color: var(--smc-primary, #0f172a);
  font-weight: 700;
}

.smc-cluster-box ul {
  margin: 0;
  padding-left: 20px;
}

.smc-cluster-box li {
  margin-bottom: 8px;
}

.smc-faq-item {
  margin-bottom: 16px;
  border: 1px solid var(--smc-border, #e2e8f0);
  border-radius: var(--smc-radius, 8px);
  padding: 16px 20px;
  background: var(--smc-surface, #f8fafc);
}

.smc-faq-item h4 {
  margin: 0 0 8px;
  font-size: 16.5px;
  color: var(--smc-primary, #0f172a);
  font-weight: 700;
}

.smc-faq-item p {
  margin: 0;
  color: #334155;
}

versions.css:
.smc-root {
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 17px;
  line-height: 1.75;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
}

.smc-root h2 {
  margin: 38px 0 16px;
  padding: 13px 16px;
  border-left: 5px solid var(--smc-accent);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
  background: color-mix(in srgb, var(--smc-surface) 86%, var(--smc-accent) 14%);
  font-size: clamp(25px, 4vw, 34px);
  line-height: 1.25;
}

.smc-root h2:first-child {
  margin-top: 0;
}

.smc-root h3 {
  margin: 28px 0 10px;
  padding: 0 0 8px;
  border-bottom: 1px solid var(--smc-border);
  font-size: clamp(20px, 3vw, 25px);
  line-height: 1.35;
}

.smc-root p {
  margin: 0 0 15px;
}

.smc-root strong {
  color: var(--smc-primary);
  font-weight: 700;
}

.smc-root a {
  color: var(--smc-accent);
  font-weight: 650;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.smc-root a:hover {
  color: var(--smc-primary);
}

.smc-root table {
  display: table !important;
  width: 100% !important;
  table-layout: fixed !important;
  margin: 20px 0 28px;
  overflow: hidden;
  border: 1px solid var(--smc-border);
  border-collapse: separate;
  border-spacing: 0;
  border-radius: var(--smc-radius);
  background: var(--smc-bg);
}

.smc-root th,
.smc-root td {
  width: auto !important;
  min-width: 0 !important;
  padding: 13px 14px;
  border-right: 1px solid var(--smc-border);
  border-bottom: 1px solid var(--smc-border);
  text-align: left;
  vertical-align: top;
}

.smc-root th {
  color: var(--smc-bg);
  background: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
}

.smc-root tr:last-child td {
  border-bottom: 0;
}

.smc-root th:last-child,
.smc-root td:last-child {
  border-right: 0;
}

.smc-root tbody tr:nth-child(even) td {
  background: var(--smc-surface);
}

.smc-root ul,
.smc-root ol {
  margin: 16px 0 24px;
  padding-left: 26px;
}

.smc-root li {
  margin: 0 0 10px;
  padding-left: 5px;
}

.smc-root ol li::marker {
  color: var(--smc-accent);
  font-weight: 800;
}

.smc-root ul li::marker {
  color: var(--smc-primary);
}

.smc-root h2:nth-last-of-type(2) + ul {
  padding: 18px 20px 12px 42px;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: var(--smc-surface);
}

@container smc (max-width: 620px) {
  .smc-root {
    font-size: 16px;
    line-height: 1.7;
  }

  .smc-root h2 {
    margin-top: 30px;
    padding: 11px 13px;
  }

  .smc-root h3 {
    margin-top: 24px;
  }

  .smc-root table {
    display: table !important;
    width: 100% !important;
    table-layout: fixed !important;
    overflow: hidden !important;
    border-radius: var(--smc-radius);
  }

  .smc-root table thead,
  .smc-root table tbody {
    min-width: 0;
  }

  .smc-root th,
  .smc-root td {
    min-width: 0 !important;
    width: auto !important;
    padding: 10px 8px;
    overflow-wrap: anywhere;
    font-size: 14px;
  }
}

